const items = $input.all();

let totalOrders = 0;
let totalRevenue = 0;
let totalCost = 0;

for (const item of items) {
  const values = Object.values(item.json);

  totalOrders += Number(values[4]);
  totalRevenue += Number(values[5]);
  totalCost += Number(values[6]);
}

const totalProfit = totalRevenue - totalCost;
const averageOrderValue = totalRevenue / totalOrders;

return [
  {
    json: {
      totalOrders,
      totalRevenue,
      totalCost,
      totalProfit,
      averageOrderValue
    }
  }
];

const items = $input.all();

let previous = {
  orders: 0,
  revenue: 0,
  cost: 0
};

let current = {
  orders: 0,
  revenue: 0,
  cost: 0
};

for (const item of items) {
  const values = Object.values(item.json);

  const date = values[1];
  const orders = Number(values[4]);
  const revenue = Number(values[5]);
  const cost = Number(values[6]);

  if (date <= "2026-10-04") {
    previous.orders += orders;
    previous.revenue += revenue;
    previous.cost += cost;
  } else {
    current.orders += orders;
    current.revenue += revenue;
    current.cost += cost;
  }
}

previous.profit = previous.revenue - previous.cost;
current.profit = current.revenue - current.cost;

const change = (currentValue, previousValue) => {
  if (previousValue === 0) return 0;
  return ((currentValue - previousValue) / previousValue) * 100;
};

return [
  {
    json: {
      previousPeriod: previous,
      currentPeriod: current,
      changes: {
        ordersPercent: change(current.orders, previous.orders),
        revenuePercent: change(current.revenue, previous.revenue),
        profitPercent: change(current.profit, previous.profit)
      }
    }
  }
];

const data = $input.first().json;

const previous = data.previousPeriod;
const current = data.currentPeriod;
const changes = data.changes;

const anomalies = [];

if (changes.ordersPercent < -20) {
  anomalies.push({
    metric: "Orders",
    severity: "High",
    message: "Orders decreased significantly."
  });
}

if (changes.revenuePercent < -20) {
  anomalies.push({
    metric: "Revenue",
    severity: "High",
    message: "Revenue decreased significantly."
  });
}

if (changes.profitPercent < -20) {
  anomalies.push({
    metric: "Profit",
    severity: "High",
    message: "Profit decreased significantly."
  });
}

if (changes.profitPercent < changes.revenuePercent - 10) {
  anomalies.push({
    metric: "Profit",
    severity: "Medium",
    message: "Profit is growing significantly slower than revenue."
  });
}

if (current.cost > previous.cost && changes.revenuePercent < changes.profitPercent) {
  anomalies.push({
    metric: "Cost",
    severity: "Medium",
    message: "Costs increased while profitability improved. Cost efficiency should be monitored."
  });
}

return [
  {
    json: {
      hasAnomalies: anomalies.length > 0,
      anomalyCount: anomalies.length,
      anomalies
    }
  }
];

const items = $input.all();

