const anomalyReport = items[1]?.json?.output || "";

const finalReport = `📊 BUSINESS REPORT

${businessReport}

⚠️ ANOMALY ANALYSIS

${anomalyReport}
`;

return [
  {
    json: {
      finalReport
    }
  }
];

const text = $json.finalReport || "";

const chunkSize = 3500;
const chunks = [];

for (let i = 0; i < text.length; i += chunkSize) {
  chunks.push(text.slice(i, i + chunkSize));
}

return chunks.map((chunk, index) => ({
  json: {
    message: chunk,
    part: index + 1,
    totalParts: chunks.length
  }
}));
